printf 'MODULE HexTest;
IMPORT Out;
VAR a: INTEGER; c: CHAR;
BEGIN
  a := 0FFH;
  Out.Int(a, 0); Out.Ln;
  a := 0A43FH;
  Out.Int(a, 0); Out.Ln;
  c := 41X;
  Out.Char(c); Out.Ln
END HexTest.' > /tmp/HexTest.Mod && ./InterOberon /tmp/HexTest.Mod && /tmp/HexTest | hexdump -C

